// Stats JSON is generated by `python -m museum stats` into src/data/ before every build.
import metaJson from '../data/meta.json';
import lobbyJson from '../data/lobby.json';
import recordsJson from '../data/records.json';
import shameJson from '../data/shame.json';
import managersJson from '../data/managers.json';
import rivalriesJson from '../data/rivalries.json';
import championsJson from '../data/champions.json';
import archivesJson from '../data/archives.json';
import seasonJson from '../data/season.json';
import funJson from '../data/fun.json';

export const meta: any = metaJson;
export const lobby: any = lobbyJson;
export const records: any[] = recordsJson as any[];
export const shame: any[] = shameJson as any[];
export const managers: any[] = managersJson as any[];
export const rivalries: Record<string, any> = rivalriesJson as any;
export const champions: any = championsJson;
export const archives: any[] = archivesJson as any[];
export const season: any = seasonJson;
export const fun: any = funJson;

const byId = new Map<string, any>(meta.managers.map((m: any) => [m.id, m]));

export function mgr(id: string | null | undefined) {
  return (id && byId.get(id)) || { id, name: id || 'Unknown', color: '#6b7280', initials: '?' };
}

/** Team logo for a manager: that season's when given (Archives), otherwise their latest. */
export function logoFor(id: string | null | undefined, season?: number | string): string | null {
  if (!id) return null;
  if (season !== undefined) return meta.logos?.[String(season)]?.[id] ?? null;
  return mgr(id).logo ?? null;
}

export const name = (id: string | null | undefined) => mgr(id).name;

const base = import.meta.env.BASE_URL.replace(/\/?$/, '/');

/** Site-relative URL honoring the GitHub Pages base path. */
export function url(path = '') {
  const clean = path.replace(/^\//, '');
  if (!clean) return base;
  const [rest, hash] = clean.split('#');
  const [p, query] = rest.split('?');
  const withSlash = p === '' || p.endsWith('/') || p.includes('.') ? p : `${p}/`;
  return base + withSlash + (query ? `?${query}` : '') + (hash ? `#${hash}` : '');
}

/** Regular season is the default everywhere; playoffs = winners' bracket; consolation is its own thing. */
export const SEGMENTS = ['regular', 'playoffs', 'all'] as const;
const SEGMENT_NAMES: Record<string, [string, string]> = {
  regular: ['Regular season', 'Regular'],
  playoffs: ['Playoffs', 'Playoffs'],
  all: ['Regular + playoffs', 'All'],
  consolation: ['Consolation', 'Consolation'],
  season: ['Full season', 'Full season'],
};
export const segmentName = (s: string, short = false) => (SEGMENT_NAMES[s] ?? [s, s])[short ? 1 : 0];
/** Which toggle states a fixed-segment card should be visible in. */
export const visibleIn = (s: string) =>
  s === 'regular' ? 'regular all' : s === 'playoffs' ? 'playoffs all' : 'regular playoffs all';
/** URL suffix for a non-default segment. */
export const segQuery = (s: string) => (s && s !== 'regular' ? `?segment=${s}` : '');

export const pairKey = (a: string, b: string) => [a, b].sort().join('--');

export function fmt(n: number | null | undefined, digits = 2) {
  if (n === null || n === undefined) return '—';
  return n.toLocaleString('en-US', { minimumFractionDigits: digits, maximumFractionDigits: digits });
}

export const latestLabel = `Week ${meta.latest.week}, ${meta.latest.season}`;

/** e.g. "Sun 3:45 PM ET" — live scrapes run on a schedule in UTC; the league thinks in Eastern time. */
export function etTime(iso: string | null | undefined) {
  if (!iso) return '';
  const d = new Date(iso);
  return d.toLocaleString('en-US', { timeZone: 'America/New_York', weekday: 'short', hour: 'numeric', minute: '2-digit' }) + ' ET';
}

export function ordinal(n: number) {
  const s = ['th', 'st', 'nd', 'rd'];
  const v = n % 100;
  return n + (s[(v - 20) % 10] || s[v] || s[0]);
}

export const recordStr = (w: number, l: number, t = 0) => `${w}-${l}${t ? `-${t}` : ''}`;

export const GLOSSARY = {
  true: { title: 'True record', text: 'Two games a week: your real head-to-head game, plus a game against the league median score that week. Beat the median and you get a second win; fall short and it\'s a second loss. That\'s why the W-L adds up to twice as many games.' },
  median: { title: 'Record vs median', text: 'Your record if every week you played the league\'s median score (the middle of all teams\' scores). It shows how often you were a top-half team, regardless of your opponent.' },
  average: { title: 'Record vs average', text: 'Your record if every week you played the league\'s average (mean) score. One huge or tiny score can drag the average, so this can differ from the median record.' },
  allplay: { title: 'All-play record', text: 'Your record if you played every other team every week. With 12 teams, that\'s 11 games a week. It measures how good your scores were, with schedule luck removed.' },
  luck: { title: 'Luck', text: 'Actual wins minus all-play expected wins (all-play win % × games played). Positive means the schedule helped you; negative means you lost games you usually win.' },
  clutch: { title: 'Clutch score', text: 'Points per playoff game minus points per regular-season game (winners\' bracket only). Positive means you score more when it matters.' },
  sos: { title: 'Strength of schedule', text: 'The average all-play win % of the opponents you faced (or still face). Higher means a tougher schedule; the rank in brackets is 1st = toughest. Opponents\' points against you is shown too where there is room.' },
  voe: { title: 'Draft grade (value over expected)', text: 'Each pick\'s points minus what that pick usually scores here: the average for the n-th player taken at that position in this league\'s finished drafts. Team value is the sum over all picks, graded on a curve within the season (A+ to F).' },
  kept: { title: 'Kept value', text: 'Points the drafted players scored while still on the drafting team\'s roster. Trades and drops stop the clock, so this rewards picks you actually kept.' },
  power: { title: 'Power score', text: 'A 0–100 weekly composite. All-play win % 40%, recent form (last 3 weeks\' average) 25%, total points for 20% and record vs the median 15%. Each part is scaled from the league\'s worst (0) to best (1) that week. Arrows compare with last week.' },
  odds: { title: 'Playoff odds', text: '10,000 simulations of the rest of the regular season and the playoff bracket. Each team\'s weekly score is drawn from its own scoring so far, pulled slightly toward the league average early in the season. Ties break on points for, like the league. Only final weeks are used, so live scores never move the odds.' },
  carry: { title: 'Carry share', text: 'A player\'s share of the team\'s regular-season starting points. "Without" swaps that player for the best eligible bench player each week to estimate the record without them.' },
} as const;
